[{"order":1,"type":"heading","text":"Mastering Server Components (RSC) vs Client Components Architecture in Next.js"},{"order":2,"type":"paragraph","text":"Next.js introduces a hybrid rendering architecture built around React Server Components (RSC). Understanding when and how to use Server Components versus Client Components is crucial for building performant, scalable web applications."},{"order":3,"type":"subheading","text":"Understanding React Server Components (RSC)"},{"order":4,"type":"paragraph","text":"By default, all components in the Next.js App Router are React Server Components. They execute exclusively on the server during the rendering phase. This architecture offers several distinct advantages:"},{"order":5,"type":"bullet_point","text":"Zero Bundle Size: Dependencies used exclusively in Server Components are not downloaded to the client browser."},{"order":6,"type":"bullet_point","text":"Direct Backend Access: Server Components can safely query databases, read the file system, or fetch internal microservices directly."},{"order":7,"type":"bullet_point","text":"Enhanced Security: Sensitive logic, API keys, and database tokens never leak to the client side."},{"order":8,"type":"subheading","text":"Understanding Client Components"},{"order":9,"type":"paragraph","text":"Client Components are standard React components rendered on the server for the initial HTML snapshot, but hydrated and executed primarily on the client. To designate a component as a Client Component, you must use the 'use client' directive at the very top of the file."},{"order":10,"type":"bullet_point","text":"Interactivity and Event Listeners: Required for handling browser events like onClick, onChange, or form submissions."},{"order":11,"type":"bullet_point","text":"State and Lifecycle Effects: Necessary when utilizing React hooks such as useState, useEffect, useReducer, and custom hooks."},{"order":12,"type":"bullet_point","text":"Browser APIs: Essential for accessing window, localStorage, or geolocation services."},{"order":13,"type":"subheading","text":"Code Implementation Example"},{"order":14,"type":"paragraph","text":"Below is an example showing how to compose a Server Component that fetches data and passes it down to an interactive Client Component."},{"order":15,"type":"code","text":"// app/counter/page.jsx (Server Component)
import InteractiveCounter from '@/components/InteractiveCounter';
import { fetchInitialCount } from '@/lib/api';

export default async function CounterPage() {
  // Fetches directly on the server with zero client bundle overhead
  const initialData = await fetchInitialCount();

  return (
    <main>
      <h1>Dashboard Overview</h1>
      <InteractiveCounter initialValue={initialData.count} />
    </main>
  );
}"},{"order":16,"type":"paragraph","text":"Now, let us define the Client Component that handles browser-side state updates and user interactions."},{"order":17,"type":"code","text":"'use client';

import { useState } from 'react';

export default function InteractiveCounter({ initialValue }) {
  const [count, setCount] = useState(initialValue);

  return (
    <div>
      <p>Current Count: {count}</p>
      <button onClick={() => setCount(count + 1)}>
        Increment
      </button>
    </div>
  );
}"},{"order":18,"type":"subheading","text":"Best Practices for Architecture Design"},{"order":19,"type":"bullet_point","text":"Push Client Components to the Leaves: Keep the 'use client' boundary as far down the component tree as possible to maximize server rendering benefits."},{"order":20,"type":"bullet_point","text":"Pass Server Components as Children: You can pass Server Components as children or props into Client Components to avoid turning the parent server component into a client component."},{"order":21,"type":"bullet_point","text":"Data Fetching Location: Always fetch data inside Server Components whenever feasible rather than using useEffect inside Client Components."}]
